package main

import (
	"html/template"
	"strings"
)

var adminTemplate = template.Must(template.New("admin").Funcs(template.FuncMap{"join": func(s []string) string { return strings.Join(s, ", ") }}).Parse(`<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Wardstone · Identity & access</title>
<style>:root{color-scheme:dark;font-family:system-ui,sans-serif;background:#10151c;color:#e7edf5}body{max-width:1160px;margin:48px auto;padding:0 24px}header{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #314052;margin-bottom:32px}h1{letter-spacing:-1px;font-size:36px}h2{margin-top:36px}h3{margin:0 0 16px}.badge{color:#83e8bc}section,.card{background:#19222d;border:1px solid #314052;border-radius:12px;padding:20px;margin:16px 0}label{display:block;margin:12px 0 5px;color:#bbcadd}input,select,textarea,button{font:inherit;box-sizing:border-box;padding:10px;border-radius:6px;border:1px solid #45576d;background:#10151c;color:#e7edf5}input:not([type=checkbox]),select,textarea{width:100%}textarea{min-height:110px}button{background:#9fe4bf;color:#102719;border:0;margin:14px 0;cursor:pointer;font-weight:650}.secondary{background:#314052;color:#fff}code{overflow-wrap:anywhere;color:#9fe4bf}small{color:#aabace}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:20px}.muted{color:#aabace}details{padding:16px 0}summary{cursor:pointer;font-weight:600}a{color:#9fe4bf}</style></head>
<body><header><div><p class="badge">CERTIFICATE-BOUND IDENTITY</p><h1>Wardstone</h1></div><div><strong>{{.User.Name}}</strong><p class="muted">Authenticated with mTLS</p></div></header>
<p>Access is denied unless a user belongs to an application's allowed groups. Administrators follow the same app policies.</p>
<nav><a href="#users">Users</a> · <a href="#apps">Applications</a> · <a href="#certificates">Certificates</a> · <a href="/ca.crt">Download CA</a> · <a href="/.well-known/openid-configuration">OIDC discovery</a> · <a href="/saml/metadata">SAML metadata</a></nav>
<h2 id="users">Users & groups</h2><div class="grid">{{range .Users}}<section><h3>{{.Name}}</h3><small><code>{{.ID}}</code></small><p>{{.Email}} · {{if .Admin}}Administrator{{else}}User{{end}}{{if .Disabled}} · Disabled{{end}}</p>
<form action="/admin/groups" method="post"><input type="hidden" name="csrf" value="{{$.CSRF}}"><input type="hidden" name="id" value="{{.ID}}"><label>Groups (comma-separated)<input name="groups" value="{{join .Groups}}"></label><button>Save groups</button></form>
{{if not .Disabled}}<details><summary>Issue client certificate</summary><form action="/admin/certificate" method="post"><input type="hidden" name="csrf" value="{{$.CSRF}}"><input type="hidden" name="id" value="{{.ID}}"><label>P12 password<input type="password" name="password" minlength="16" maxlength="256" required autocomplete="new-password"></label><small>Choose at least 16 characters. Save it before downloading.</small><br><button>Download .p12</button></form></details>{{if not .Admin}}<form action="/admin/disable" method="post"><input type="hidden" name="csrf" value="{{$.CSRF}}"><input type="hidden" name="id" value="{{.ID}}"><button class="secondary">Disable user</button></form>{{end}}{{end}}</section>{{end}}</div>
<details class="card"><summary>Add user</summary><form action="/admin/user" method="post"><input type="hidden" name="csrf" value="{{.CSRF}}"><label>Name<input name="name" required maxlength="128"></label><label>Email<input type="email" name="email"></label><label>Groups<input name="groups" placeholder="staff, engineering"></label><label><input type="checkbox" name="admin"> Administrator</label><button>Create user</button></form></details>
<h2 id="apps">Applications & access policies</h2><div class="grid">{{range .Apps}}<section><h3>{{.Name}}</h3><p>{{.Protocol}} · <code>{{.ID}}</code></p>{{range .Redirects}}<p>Redirect: <code>{{.}}</code></p>{{end}}<form action="/admin/policy" method="post"><input type="hidden" name="csrf" value="{{$.CSRF}}"><input type="hidden" name="id" value="{{.ID}}"><label>Allowed groups (any match)<input name="groups" value="{{join .Groups}}"></label><small>An empty list denies everyone.</small><br><button>Save access policy</button></form></section>{{else}}<p class="muted">No applications registered yet.</p>{{end}}</div>
<details class="card"><summary>Add application</summary><form action="/admin/app" method="post"><input type="hidden" name="csrf" value="{{.CSRF}}"><label>Name<input name="name" required></label><label>Protocol<select name="protocol"><option value="oidc">OpenID Connect</option><option value="saml">SAML 2.0</option></select></label><label>Allowed groups<input name="groups" placeholder="staff"></label><label>OIDC redirect URI<input name="redirect" type="url" placeholder="https://app.example.com/callback"></label><label>OIDC client secret<input name="secret" type="password" autocomplete="new-password"></label><small>OIDC: choose and save a random secret of at least 32 characters. Authorization code flow requires PKCE S256 and client_secret_basic.</small><label>SAML SP metadata<textarea name="metadata" placeholder="Paste the application's EntityDescriptor XML"></textarea></label><button>Register application</button></form></details>
<h2 id="certificates">Client certificates</h2>{{range .Certificates}}<section><code>{{.Fingerprint}}</code><p>User: <code>{{.UserID}}</code> · Expires: {{.Expires}} · {{if .Revoked}}Revoked{{else}}Active{{end}}</p>{{if not .Revoked}}<form action="/admin/revoke" method="post"><input type="hidden" name="csrf" value="{{$.CSRF}}"><input type="hidden" name="fingerprint" value="{{.Fingerprint}}"><button class="secondary">Revoke certificate</button></form>{{end}}</section>{{end}}
<p class="muted">Wardstone · Certificate-bound identity. Policy-defined access.</p></body></html>`))
